	var foreign NotaFiscal

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, notaFiscalCupomFiscalDBTypes, false, notaFiscalCupomFiscalColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize NotaFiscalCupomFiscal struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, notaFiscalDBTypes, false, notaFiscalColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize NotaFiscal struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.NTFID = foreign.NTFID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.NTF().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.NTFID != foreign.NTFID {
		t.Errorf("want: %v, got %v", foreign.NTFID, check.NTFID)
	}

	ranAfterSelectHook := false
	AddNotaFiscalHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *NotaFiscal) error {
		ranAfterSelectHook = true
		return nil
	})

